import{_ as t,H as i,f as a,i as l}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"12 | 博观约取：重走NLP领域预训练模型的长征路","description":"","frontmatter":{},"headers":[{"level":2,"title":"RNN：生而 NLP 的神经网络","slug":"rnn-生而-nlp-的神经网络","link":"#rnn-生而-nlp-的神经网络","children":[]},{"level":2,"title":"x","slug":"x","link":"#x","children":[]},{"level":2,"title":"h","slug":"h","link":"#h","children":[]},{"level":2,"title":"LSTM：解决主要矛盾，扫清前进障碍","slug":"lstm-解决主要矛盾-扫清前进障碍","link":"#lstm-解决主要矛盾-扫清前进障碍","children":[]},{"level":2,"title":"C","slug":"c","link":"#c","children":[]},{"level":2,"title":"h","slug":"h-1","link":"#h-1","children":[]},{"level":2,"title":"Seq2Seq：一统架构，众人拾柴火焰高","slug":"seq2seq-一统架构-众人拾柴火焰高","link":"#seq2seq-一统架构-众人拾柴火焰高","children":[]},{"level":2,"title":"注意力机制：集中精力办大事，好钢用在刀刃上","slug":"注意力机制-集中精力办大事-好钢用在刀刃上","link":"#注意力机制-集中精力办大事-好钢用在刀刃上","children":[]},{"level":2,"title":"C","slug":"c-1","link":"#c-1","children":[]},{"level":2,"title":"C","slug":"c-2","link":"#c-2","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"AI大模型系统实战/12｜博观约取：重走NLP领域预训练模型的长征路.md","filePath":"AI大模型系统实战/12｜博观约取：重走NLP领域预训练模型的长征路.md","lastUpdated":1795452834000}'),n={name:"AI大模型系统实战/12｜博观约取：重走NLP领域预训练模型的长征路.md"};function r(p,e,s,o,h,E){return i(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_12-博观约取-重走nlp领域预训练模型的长征路" tabindex="-1">12 | 博观约取：重走NLP领域预训练模型的长征路 <a class="header-anchor" href="#_12-博观约取-重走nlp领域预训练模型的长征路" aria-label="Permalink to &quot;12 | 博观约取：重走NLP领域预训练模型的长征路&quot;">​</a></h1><p>你好，我是 Tyler。</p><p>上节课，我们学习了计算机视觉领域预训练模型（PTM）的发展历程和重要成果，了解到CNN 的平移不变性和边缘提取能力为视觉任务提供了巨大的帮助。</p><p>不过你可能会问，上节课学到的 CNN 是根据生物的视觉结构而设计的，我总不能用 CNN 来处理自然语言问题吧？</p><p>虽然这样也不是不行，不过 NLP 领域确实有自己更偏好的模型结构。在这节课，我将带你解决自然语言处理领域所独有的一些问题，重走 NLP “长征路”，看看 NLP 模型预训练技术在黎明前都经历过哪些考验。</p><h2 id="rnn-生而-nlp-的神经网络" tabindex="-1">RNN：生而 NLP 的神经网络 <a class="header-anchor" href="#rnn-生而-nlp-的神经网络" aria-label="Permalink to &quot;RNN：生而 NLP 的神经网络&quot;">​</a></h2><p>我们第一个要学习的模型是循环神经网络（Recurrent Neural Network，RNN），它是一种用于处理“序列数据”的神经网络模型。</p><p>RNN 引入了循环结构，如下图所示，在 RNN 中，每个单元都具有一个隐藏状态来存储之前的信息，并将其传递给下一个节点。</p><h2 id="x" tabindex="-1">x <a class="header-anchor" href="#x" aria-label="Permalink to &quot;x&quot;">​</a></h2><p>如下图所示，每个单元 i 不仅仅接收自身的输入</p><ul><li>来获取当前步骤的文本信息，同时还接收​i</li></ul><h2 id="h" tabindex="-1">h <a class="header-anchor" href="#h" aria-label="Permalink to &quot;h&quot;">​</a></h2><p>前一个单元的输出</p><ul><li>作为另一部分输入，获得上下文信息的补充。i−1​</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/12/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/12/1.png" alt=""></a></p><p>就像前面学习 CNN 的时候一样，从生物尤其是人类的智能中寻找灵感这种做法，在 AI 领域屡见不鲜。</p><p>所以你发现没有？RNN 这样的结构就类似人类语言的模式。在人类对话中，我们也会不断结合之前听到的内容来理解当前语境的含义。因此，RNN 恰好适合用来给 NLP 中的长序列数据建模，这也是为什么我在小标题里强调，RNN 天生适合做 NLP 任务。</p><h2 id="lstm-解决主要矛盾-扫清前进障碍" tabindex="-1">LSTM：解决主要矛盾，扫清前进障碍 <a class="header-anchor" href="#lstm-解决主要矛盾-扫清前进障碍" aria-label="Permalink to &quot;LSTM：解决主要矛盾，扫清前进障碍&quot;">​</a></h2><p>还记得上节课我们学到的 CNN 在网络层数增加时，提到的梯度爆炸或消失问题吗？这个问题不仅在 CNN 中会出现，在 RNN 中也同样存在。</p><p>在处理较长序列时，RNN 会展开成多层，导致同一权重参数在各个单元中复制。在反向传播过程中，这些参数的梯度可能在复制时成倍地增长或减少，最终甚至出现梯度爆炸或消失的问题。</p><p>所以如果不能解决这个问题，RNN 这项面向长序列设计的技术将很难推广。所以这时 LSTM（Long short-term memory）模型应运而生，解决了这个难题。</p><p>LSTM 是一种特殊的 RNN，其内部包含三个关键的门控制单元：遗忘门、输入门和输出门。这些“门”控制了信息的流动和保留，使网络能够有选择地记住或遗忘相关信息，从而有效解决了梯度消失和爆炸问题。</p><p>你可以先看看后面的网络架构图，再听我具体分析。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/12/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/12/2.png" alt=""></a></p><ul><li><p>LSTM 网络架构</p></li><li><p>遗忘门使用 Sigmoid 激活函数计算遗忘值，输出一个介于 0 和 1 之间的值，表示要保留多少之前的记忆。</p></li><li><p>输入门使用 Tanh 激活函数计算一个新的记忆值。而且同样使用 Sigmoid 激活函数来算出一个介于 0 和 1 之间的值，表示保留的新记忆值量的多少。</p></li><li><p>输出门使用 Sigmoid 激活函数保留输入信息，并使用 Tanh 激活函数取得记忆细胞内容，配合控制输出值。</p></li></ul><p>这里我想提醒你注意，在后续的学习中，你会频繁发现 Sigmoid 被用作门控的激活函数。你可以思考一下为什么这样设计？在你自己设计模型时，是不是也可以尝试使用 Sigmoid 作为门限激活函数。</p><h2 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h2><p>我们继续回到 LSTM 的主题，结合上面的这张图，你会发现，我们引入的</p><ul><li>这条链路扮演着​t</li></ul><h2 id="h-1" tabindex="-1">h <a class="header-anchor" href="#h-1" aria-label="Permalink to &quot;h&quot;">​</a></h2><p>记忆细胞的角色，负责传递着各个门和单元之间的信息。虽然之前的 RNN 也可以依靠</p><ul><li>这​t</li></ul><p>条链路来传递局部的时序语义关系，但是记忆细胞可以捕捉并传递更长序列的语义关系，这能帮助模型更好地建模长距离依赖的关系。</p><h2 id="seq2seq-一统架构-众人拾柴火焰高" tabindex="-1">Seq2Seq：一统架构，众人拾柴火焰高 <a class="header-anchor" href="#seq2seq-一统架构-众人拾柴火焰高" aria-label="Permalink to &quot;Seq2Seq：一统架构，众人拾柴火焰高&quot;">​</a></h2><p>随着研究的深入，人们发现在 NLP 领域中，经常需要处理“输入为序列，输出也为序列”的任务，ChatGPT 就是典型的应用。</p><p>为了更好地解决这些问题，研究者将这一类任务抽象为 “Seq2Seq”（Sequence-to-Sequence）任务，并为此提出编码器 - 解码器的架构。</p><p>在技术层面上，相比直接使用序列模型进行预测，这一架构能够处理不定长度的序列，灵活性更高，也为引入各种机制（如注意力机制）提供了更多的操作空间。</p><p>如果你认真学习了前面的课程，理解编、解码器的工作原理将非常轻松。我们以机器翻译为例来带你梳理一下。</p><p>在这个过程中，首先编码器会将输入序列从源空间（例如中文）投影到一个高维语义空间的向量表示中。接着，解码器将这个高维向量从语义空间映射回目标空间（例如英文），生成一个新的序列作为翻译输出。</p><p>这是不是和特征工程那节课学习的知识很像？你只是在做各个语义空间中的相互投影罢了，只不过这个投影的方法叫做编码器和解码器。</p><p>下面的图片直观展示了编码器 - 解码器的工作过程，我们一起来看看。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/12/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/12/3.png" alt=""></a></p><p>在编码器（Encoder）中，输入序列经过 RNN，更新每一个单元的隐藏状态，并用最后一个单元的隐藏状态，作为编码器阶段产出的高维向量，因为它包含了完整输入序列的语义信息。</p><p>接着，解码器（Decoder）用编码器产出的高维向量，作为自己的初始隐藏状态向后传递，“报出”自己的内容，并且向后面的 RNN 单元传递更新后的状态。当后面的 RNN 单元传递接收到前一步的输入时，也会“报出”自己的内容，并继续向下一个单元传递隐藏状态，直到持续生成完整的目标序列。</p><p>这种架构的价值在于它规范这类问题的解决范式，促使全球的研究人员达成共识，这可以凝聚该领域的多数力量共同建设发展。</p><h2 id="注意力机制-集中精力办大事-好钢用在刀刃上" tabindex="-1">注意力机制：集中精力办大事，好钢用在刀刃上 <a class="header-anchor" href="#注意力机制-集中精力办大事-好钢用在刀刃上" aria-label="Permalink to &quot;注意力机制：集中精力办大事，好钢用在刀刃上&quot;">​</a></h2><p>你会发现，我们刚刚学习的 LSTM 在编码器阶段，将所有输入信息都被“压缩”到了一个固定长度的向量中——也就是最后一个 RNN 单元的隐层表示。</p><p>你也许会疑惑，这么狭小的空间真的能够容纳如此丰富的信息吗？</p><p>这是个很好的问题，因为这种“压缩”确实可能会导致关键信息的流失。正因如此，为了更加有效地捕捉输入序列中的关键信息，我们就需要引入注意力机制。</p><p>这里我举个例子来帮你理解注意力机制。综艺节目里有个非常经典的节目——“传声筒游戏”。在这个游戏中，通常会有 N 个参与者，每个人有一个编号。每个人只能听取编号比自己小的人传来的话，同时只能将这段话传递给编号比自己大的下一个人。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/12/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/12/4.png" alt=""></a></p><p>这个游戏本身确实具有一定难度，因为它需要考验每一个人在过程中的记忆和表达能力。但是，如果我们稍作改变，允许后面的人与之前所有的人进行对话，那么游戏的难度就会大大降低。</p><p>而 Attention 就是在做这个事情，它允许后面的人询问（Query）他前面所有人知道的内容（Key &amp; Value），甚至后面的人还能知道之前哪个人说的话对他来说是“更重要的”，是不是感觉这太过“作弊”了？</p><p>没错，注意力机制的思路和原先的循环结构相比，简直是开了挂，这正是它的强大之处。</p><h2 id="c-1" tabindex="-1">C <a class="header-anchor" href="#c-1" aria-label="Permalink to &quot;C&quot;">​</a></h2><p>具体来说，类似于在 LSTM 中我们引入</p><ul><li>这条记忆链路，使得模型能够更好地建模长距离依​t</li></ul><h2 id="c-2" tabindex="-1">C <a class="header-anchor" href="#c-2" aria-label="Permalink to &quot;C&quot;">​</a></h2><p>赖的关系。如下图所示，Attention 则是为解码器阶段的每个单元，单独准备了一个自己的，它会基于当前单元内容和输入之间的关系进行“私人定制”，让解码器的每个单元都能获得定制化的全局信息。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/12/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/12/5.png" alt=""></a></p><p>Attention 机制的出色表现让 AI 领域的研究人员都感到兴奋不已，纷纷直呼“真香”。于是，Google 的研究人员产生了一个有趣的想法：如果只用 Attention 这一招，会不会更香？</p><p>他们并没有停留在猜想环节，Google AI 的论文 “Attention Is All You Need”应运而生。这就是大名鼎鼎的 Transformer，灵感正是来自于“注意力机制”。即便 NLP 模型发展如此迅猛，还是没有走出自己的预训练模型之路，不过 Transformer 的出现为这一切带来了转机，后面的故事我下节课再为你揭秘。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>让我们总结一下。这节课我带你一起梳理了语言模型的发展历程。理解了这条脉络，也有助于你后续更好地学习大型语言模型（LLM）。</p><p>还是那句话，我们要自顶而下地学习，所以如果你之前没什么机器学习基础的话，这节课你可以先把重点放在串联技术发展脉络上。</p><p>其实，语言模型的发展历程与视觉模型有许多相似之处。例如，它们都考虑了生物行为的特点，找到了适合自身的神经网络结构——循环神经网络（RNN）和卷积神经网络（CNN）。</p><p>它们在模型规模不断扩大的过程中，也都遇到了梯度爆炸和梯度消失的问题，并基于各自模型结构的特点找到了应对方法，分别是 LSTM 和 ResNet。</p><p>这种相似的发展轨迹，也许给当时的人们带来了一些“启发”，他们隐约认识到，或许存在一种方法能够对不同模态的数据进行“大一统”的建模。在后续课程的多模态算法部分，我会再次与你讨论这个问题。</p><p>希望你在课后认真吸收消化这节课的内容，认真理解语言模型所涉及的场景特点。在下一节课开始时，我将带领你正式踏入大型语言模型（LLM）的领域，共同探索其中的奥秘。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>这节课我们学习了如何给 LSTM 增加 Attention 机制，你可以思考一下，如果要给上节课学到的 CNN 增加这个机制，该如何做呢？</p></li><li><p>沿着课程中传声筒游戏可以“作弊”的思路想下去，你还能想出哪些作弊方法？越离谱越好！</p></li></ol><p>恭喜完成我们第 12 次打卡学习，期待你在留言区和我交流互动。如果你觉得有收获，也欢迎你分享给你身边的朋友，邀 TA 一起讨论。</p>',72)])])}const N=t(n,[["render",r]]);export{u as __pageData,N as default};
